// Shared field schemas (task T032). Kept in one module so evidence.ts and finding.ts can both use
// them without importing each other.
import { z } from "zod";

/** RFC 3339 UTC date-time ending in "Z"; fractional seconds allowed, offsets rejected. */
export const UtcDateTimeSchema = z.iso.datetime();

/** RFC 3339 UTC date-time at exactly second precision ("YYYY-MM-DDTHH:MM:SSZ"). */
export const UtcSecondsSchema = z.iso.datetime({ precision: 0 });

/** Audits are identified by a UUID v4 generated by the web service (data-model.md). */
export const AuditIdSchema = z.uuidv4();

/** sha256(kind + ":" + ruleId), truncated to 16 lowercase hex characters. */
export const FindingIdSchema = z.string().regex(/^[0-9a-f]{16}$/);

/** HMAC-SHA256 tag as unpadded base64url (43 characters). */
export const EvidenceSignatureSchema = z.string().regex(/^[A-Za-z0-9_-]{43}$/);

// RFC 3986 URI characters, with well-formed percent-escapes. `z.url()` alone accepts spaces.
const URI_CHARACTERS = /^(?:[A-Za-z0-9\-._~:/?#[\]@!$&'()*+,;=]|%[0-9A-Fa-f]{2})*$/;

/** An absolute URI whose scheme is exactly lowercase "https" (case-sensitive, as in the contract). */
export const HttpsUrlSchema = z
  .url()
  .regex(/^https:\/\//, "must start with lowercase https://")
  .regex(URI_CHARACTERS, "must be a valid URI");

export const ImpactSchema = z.enum(["critical", "serious", "moderate", "minor"]);
export type Impact = z.infer<typeof ImpactSchema>;
